import * as k from '../anatomy/iso-kit.mjs';
export function atlas(kind){const P=k.fitProjection(k.boxCorners({x:-80,y:-50,w:160,d:100,r:2},-8,110),420,260,{pad:20,azimuth:35,elevation:30});const S=(x,y,w,d,z,h,tone='mid')=>k.solidSvg(k.slabOf({x,y,w,d,r:Math.min(1,w/4)},z,h,P,3,.4),{tone});let out='';for(const x of [-70,70])for(const y of [-40,40])out+=S(x-4,y-4,8,8,-8,5,'lo');out+=S(-80,-50,160,100,-3,3,'lo');for(const x of [-72,72])for(const y of [-42,42])out+=S(x-2,y-2,4,4,0,1,'hi');if(kind==='dual'){for(const y of [-34,7]){out+=S(-8,y,65,3,16,22);for(const x of [-8,53])out+=S(x,y,4,24,0,38);out+=S(15,y+3,4,18,17,20,'hi');out+=S(19,y+10,54,4,25,4,'hi');for(const x of [-5,54])out+=S(x,y+8,4,7,38,3,'lo');out+=S(-45,y+6,28,18,0,10);for(let j=0;j<5;j++)out+=S(-43+j*5,y+23,2,5,3,3,'hi');}for(let j=0;j<7;j++){out+=S(-38+j*13,35,11,12,0,22,j?'mid':'lo');for(let i=0;i<3;i++)out+=S(-37+j*13+i*3,36,1,10,22,1,'lo');}}else if(kind==='pneumatic'||kind==='plc'){out+=S(-66,-22,32,40,0,9);out+=k.solidSvg(k.cylinder(-50,-2,16,9,37,P,48),{tone:'mid'});out+=S(-62,-15,24,26,46,6);for(let j=0;j<6;j++)out+=S(-61,-14,22,24,52+j*3,1,'lo');out+=S(-11,-35,78,5,20,28);out+=S(-11,-30,5,30,20,28);out+=S(62,-30,5,30,20,28);out+=S(22,-29,5,28,21,26,'hi');out+=S(27,-17,48,5,32,5,'hi');for(const x of [-8,64])for(const y of [-28,-3])out+=S(x-2,y-2,4,4,48,2,'hi');out+=S(-17,12,48,26,0,9);out+=S(-12,16,38,18,9,8);for(const x of [-10,0,10,20])out+=S(x,14,3,22,17,2,'hi');for(let j=0;j<5;j++)out+=S(-12+j*9,38,4,7,3,4,'hi');for(const x of [0,25]){out+=S(x,-1,4,13,7,4,'lo');out+=S(x,-4,4,4,7,15,'lo');}for(let j=0;j<10;j++)out+=S(40+j*3,18,1,12,0,1,'lo');}else if(kind==='engine'){out+=S(-30,-20,60,45,0,8);out+=S(-30,-20,60,5,8,80);for(let i=0;i<8;i++)out+=S(-34,-23,68,4,18+i*8,2,'lo');out+=S(-18,-8,36,28,55,18,'hi');out+=S(-4,0,8,8,15,40);out+=S(-32,-20,64,45,88,7);for(const x of [-15,15]){out+=S(x-2,0,4,4,95,13,'hi');for(let i=0;i<5;i++)out+=S(x-4,-2,8,8,96+i*2,1,'lo')}}else if(kind==='hydraulic'){for(const [x,w,z]of [[-45,24,65],[35,45,45]]){out+=S(x-w/2,-20,w,40,0,5);out+=S(x-w/2,-20,w,4,5,70);out+=S(x-w/2,-16,4,32,5,70);out+=S(x+w/2-4,-16,4,32,5,70);out+=S(x-w/2+4,-16,w-8,32,5,z-5,'lo');out+=S(x-w/2+4,-16,w-8,32,z,4,'hi');out+=S(x-3,-3,6,6,z+4,25,'hi');out+=S(x-w/2,-20,w,40,z+29,4);for(let j=0;j<8;j++)out+=S(x-w/2-4,-20,3,4,8+j*8,1,'hi')}}else{out+=S(-60,-30,120,60,0,7);for(const y of [-22,22])out+=S(-54,y,108,6,7,50);for(let i=0;i<14;i++)out+=S(-50+i*7,-29,2,58,57,3,'lo');out+=S(-56,-10,112,20,25,20,'hi');out+=S(-72,-4,145,8,31,8,'hi');for(const x of [-55,55]){out+=S(x-4,-27,8,54,8,50);for(const y of [-22,22])out+=S(x-2,y-2,4,4,58,2,'hi')}out+=S(-15,-12,30,24,60,12);for(const x of [-8,0,8])for(const y of [-5,5])out+=S(x-1,y-1,2,2,72,3,'hi')};if(kind==='plc'){for(let i=0;i<4;i++){out+=S(-15+i*18,22,15,17,19,23,i?'mid':'hi');for(let j=0;j<4;j++)out+=S(-13+i*18+j*3,23,1,13,42,1,'lo');}}return k.figureSvg({width:420,height:260,label:'Ficha isométrica del ensamblaje construida con Anatomy',body:[out]});}
